po4 = []
for line in open(p):
    if line.startswith("HETATM") and line[17:20].strip()=="PO4":
        po4.append((line[21], line[22:27].strip(), line[12:16].strip(),
                    float(line[30:38]), float(line[38:46]), float(line[46:54])))
for r in po4: print(r)

arr = np.array([[r[3],r[4],r[5]] for r in po4])
print("PO4 all centroid:", np.round(arr.mean(axis=0),2))
# per-chain
import collections
g = collections.defaultdict(list)
for r in po4: g[(r[0],r[1])].append([r[3],r[4],r[5]])
for k,v in g.items(): print(k, np.round(np.array(v).mean(axis=0),2))

